from pathlib import Path
from html import escape
import json
D=Path('dist');D.mkdir(exist_ok=True)
arrow='<img class="arrow" src="assets/arrow-up-right.svg" alt="" width="24" height="24">'
def btn(text,url='contact.html',outline=False):return f'<a class="button {"outline" if outline else ""}" href="{url}">{text}{arrow}</a>'
def media(label,w=1200,h=900):return f'<div class="media" style="--ratio:{w}/{h}" role="img" aria-label="Blank placeholder: {label}, {w} by {h} pixels"><span>{label}<small>{w} × {h} px</small></span></div>'
nav=[('about','Who we are'),('services','What we offer'),('insights','Insights'),('contact','Contact us')]
def header(page):return '<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="Geojit Private Wealth home"><img src="assets/logo.svg" width="166" height="64" alt="Geojit Private Wealth"><span>DIFC · Dubai</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="primary-nav">Menu <span aria-hidden="true">+</span></button><nav id="primary-nav" aria-label="Main navigation">'+''.join(f'<a href="{p}.html" {"aria-current=page" if p==page else ""}>{t}</a>' for p,t in nav)+btn('Start a conversation',outline=True)+'</nav></div></header>'
def footer():return '<footer><div class="container"><div class="footer-grid"><div><a href="index.html"><img src="assets/logo.svg" width="166" height="64" alt="Geojit Private Wealth"></a><p class="small">Geojit Private Wealth (DIFC) Limited</p><p class="small muted">N401, 4th Floor, Emirates Financial Towers<br>DIFC, Dubai, UAE</p></div><div><h2 class="footer-title">Explore</h2>'+''.join(f'<a href="{p}.html">{t}</a>' for p,t in nav)+'</div><div><h2 class="footer-title">Our solutions</h2>'+''.join(f'<a href="services.html#{s[0]}">{s[1]}</a>' for s in services)+'</div><div><h2 class="footer-title">Get in touch</h2><a href="tel:+97142850019">+971 4 285 0019</a><a href="mailto:corporate@geojitdifc.com">corporate@geojitdifc.com</a><a href="mailto:corporate@geojitdifc.com?subject=Legal%20and%20privacy%20documents">Request legal &amp; privacy documents</a></div></div><div class="footer-bottom"><span>© 2026 Geojit Private Wealth (DIFC) Limited</span><a href="#top">Back to top ↑</a></div></div></footer>'
